func GuidelineCodes() []string {
	o := make([]string, 0, len(Guidelines))
	for _, g := range Guidelines {
		o = append(o, g.Code)
	}
	return o
}
func GuidelineWeight(code string) int {
	for _, g := range Guidelines {
		if g.Code == code {
			return g.Weight
		}
	}
	return 0
}
func RequiredGuidelines() []Guideline {
	o := []Guideline{}
	for _, g := range Guidelines {
		if g.Weight >= 3 {
			o = append(o, g)
		}
	}
	return o
}
